/// <reference types="bun" />
// HalfCheetah-v4 decoder unit tests: the reset port that synthesizes frame -1,
// the pose/velocity decode, and the teleport rule.
//
// Oracle: test/fixtures/init_states.json, generated by gen_classic.py from the
// same Philox draw order as Sources/OakPhysics.metal and CERTIFIED by seeding
// fp64 MuJoCo with the derived (qpos, qvel) and replaying the recorded ctrl of
// .oak-benchmarks/frontend-demo-16env-20260803 (max |err| ~8e-7 over 30 steps,
// which is fp32-vs-fp64 drift). That certification is re-asserted here so a
// regenerated fixture cannot quietly lose it.
//
// Precision: qpos is bitwise-exact (uniform draws only). qvel goes through
// Box-Muller, whose log/cos/sin are libm calls, so numpy and V8 can differ in
// the last float32 ulp (~3e-8 measured); it is compared with a 1e-6 tolerance.

import { describe, expect, test } from 'bun:test';
import { readFileSync } from 'node:fs';

import { CHEETAH_RADIUS, CHEETAH_HEAD_RADIUS, ROOT_Z0, fk } from '@sim/fk/cheetah';
import {
  CHEETAH_DT,
  CHEETAH_TELEPORT_DX,
  HC_FRAME_SKIP,
  HC_RESET_NOISE,
  HC_TIMESTEP,
  QPOS_LEN,
  cheetahReset,
  halfCheetahDecoder,
} from '@sim/envs/halfcheetah';
import type { CheetahState, CheetahStatic } from '@sim/envs/halfcheetah';
import { RECORD_FLOATS } from '@sim/record';
import type { EnvFrame } from '@sim/types';

const QVEL_TOL = 1e-6;

interface InitSeedRow {
  seed: number;
  pose: number[];
  qvel?: number[];
}
interface InitDoc {
  version: number;
  envs: Record<string, {
    seeds: InitSeedRow[];
    resetValidation?: {
      validated: boolean;
      lanes: { seed: number; steps: number; err0: number; errMax: number }[];
    };
  }>;
}

const initDoc = JSON.parse(
  readFileSync(new URL('../fixtures/init_states.json', import.meta.url), 'utf8'),
) as InitDoc;
const CHEETAH = initDoc.envs['HalfCheetah-v4'];

/** Build a record row with the given pose (and optional ctrl/done). */
function row(pose: number[], done = 0, ctrl: number[] = []): Float32Array {
  const r = new Float32Array(RECORD_FLOATS);
  for (let i = 0; i < ctrl.length && i < 6; i++) r[i] = ctrl[i] ?? 0;
  r[6] = done;
  for (let i = 0; i < pose.length && i < 9; i++) r[7 + i] = pose[i] ?? 0;
  return r;
}

function frameOf(i: number, r: Float32Array, prev: EnvFrame<CheetahState>): EnvFrame<CheetahState> {
  return halfCheetahDecoder.decodeFrame(i, r, STATIC, prev);
}

const STATIC: CheetahStatic = halfCheetahDecoder.initStatic(0);

describe('cheetah reset port', () => {
  test('fixture carries its fp64 MuJoCo certification', () => {
    const v = CHEETAH?.resetValidation;
    expect(v?.validated).toBe(true);
    expect(v?.lanes.length).toBe(8);
    for (const lane of v?.lanes ?? []) {
      expect(lane.steps).toBeGreaterThanOrEqual(30);
      expect(lane.err0).toBeLessThan(1e-6);
      expect(lane.errMax).toBeLessThan(1e-4);
    }
  });

  test('qpos is bit-exact against the Python port for all 8 lanes', () => {
    expect(CHEETAH?.seeds.length).toBe(8);
    for (const want of CHEETAH?.seeds ?? []) {
      const { qpos } = cheetahReset(want.seed, 0);
      expect(qpos.length).toBe(QPOS_LEN);
      expect(Array.from(qpos)).toEqual(want.pose);
    }
  });

  test('qvel matches to within a float32 ulp for all 8 lanes', () => {
    for (const want of CHEETAH?.seeds ?? []) {
      const { qvel } = cheetahReset(want.seed, 0);
      const ref = want.qvel ?? [];
      expect(ref.length).toBe(QPOS_LEN);
      for (let i = 0; i < QPOS_LEN; i++) {
        expect(Math.abs((qvel[i] ?? NaN) - (ref[i] ?? NaN))).toBeLessThan(QVEL_TOL);
      }
    }
  });

  test('qpos stays inside the U(-0.1, 0.1) reset noise band', () => {
    for (const want of CHEETAH?.seeds ?? []) {
      const { qpos } = cheetahReset(want.seed, 0);
      for (const v of qpos) {
        expect(v).toBeGreaterThanOrEqual(-HC_RESET_NOISE);
        expect(v).toBeLessThan(HC_RESET_NOISE);
      }
    }
  });

  test('different lanes and reset indices draw different states', () => {
    const a = cheetahReset(0, 0).qpos;
    const b = cheetahReset(1, 0).qpos;
    const c = cheetahReset(0, 1).qpos;
    expect(Array.from(a)).not.toEqual(Array.from(b));
    expect(Array.from(a)).not.toEqual(Array.from(c));
  });
});

describe('constants mirror the kernel', () => {
  test('control step is frameSkip * timestep', () => {
    expect(HC_FRAME_SKIP).toBe(5);
    expect(HC_TIMESTEP).toBe(0.01);
    expect(CHEETAH_DT).toBe(0.05);
    expect(Math.fround(HC_FRAME_SKIP * HC_TIMESTEP)).toBe(Math.fround(CHEETAH_DT));
  });
});

describe('decoder contract', () => {
  test('identity', () => {
    expect(halfCheetahDecoder.envId).toBe('HalfCheetah-v4');
    expect(halfCheetahDecoder.needsReplay).toBe(false);
  });

  test('geometry exposes the frozen cheetah FK', () => {
    const g = halfCheetahDecoder.geometry(STATIC, 0);
    expect(g.kind).toBe('cheetah');
    expect(g.cheetah?.radius).toBe(CHEETAH_RADIUS);
    expect(g.cheetah?.headRadius).toBe(CHEETAH_HEAD_RADIUS);
    // the same fk the kit renders with
    const a = g.cheetah?.fk(new Float32Array(9));
    const b = fk(new Float32Array(9));
    expect(Array.from(a ?? [])).toEqual(Array.from(b));
    // stable singleton across calls
    expect(halfCheetahDecoder.geometry(STATIC, 0)).toBe(g);
  });

  test('init frame is step -1 with the reset qpos and the reset qvel[0]', () => {
    const f = halfCheetahDecoder.initFrame(0, STATIC);
    expect(f.step).toBe(-1);
    expect(f.done).toBe(0);
    expect(Array.from(f.ctrl)).toEqual([0, 0, 0, 0, 0, 0]);
    expect(Array.from(f.pose)).toEqual(Array.from(STATIC.initQpos));
    expect(f.state.velX).toBe(STATIC.initQvel[0] ?? NaN);
    expect(f.state.rootX).toBe(STATIC.initQpos[0] ?? NaN);
    expect(f.state.rootZ).toBe(ROOT_Z0 + (STATIC.initQpos[1] ?? NaN));
    expect(f.state.pitch).toBe(STATIC.initQpos[2] ?? NaN);
  });

  test('init frame pose does not alias the static reset draw', () => {
    const f = halfCheetahDecoder.initFrame(0, STATIC);
    expect(f.pose).not.toBe(STATIC.initQpos);
    f.pose[0] = 99;
    expect(STATIC.initQpos[0]).not.toBe(99);
  });

  test('decodeFrame reads pose from offset 7 and ctrl from offset 0', () => {
    const pose = [1, 2, 3, 4, 5, 6, 7, 8, 9];
    const ctrl = [-1, -0.5, 0, 0.5, 1, 0.25];
    const prev = halfCheetahDecoder.initFrame(0, STATIC);
    const f = frameOf(3, row(pose, 0, ctrl), prev);
    expect(f.step).toBe(3);
    expect(Array.from(f.pose)).toEqual(pose);
    expect(Array.from(f.ctrl)).toEqual(ctrl);
    expect(f.state.qpos).toBe(f.pose);
    expect(f.state.rootX).toBe(1);
    expect(f.state.rootZ).toBe(ROOT_Z0 + 2);
    expect(f.state.pitch).toBe(3);
  });

  test('velX is the env xv: (dx) / (frameSkip * timestep)', () => {
    const prev = frameOf(0, row([1, 0, 0]), halfCheetahDecoder.initFrame(0, STATIC));
    const next = frameOf(1, row([1.25, 0, 0]), prev);
    expect(next.state.velX).toBe(0.25 / CHEETAH_DT);
    // 1.25 and 1.15 are not exact in float32, so the delta is close, not equal
    const back = frameOf(2, row([1.15, 0, 0]), next);
    expect(back.state.velX).toBeCloseTo(-0.1 / CHEETAH_DT, 5);
  });
});

describe('events', () => {
  const base = halfCheetahDecoder.initFrame(0, STATIC);

  test('an ordinary transition fires nothing', () => {
    const a = frameOf(0, row([0.1, 0, 0]), base);
    const b = frameOf(1, row([0.2, 0, 0]), a);
    expect(halfCheetahDecoder.deriveEvents(a, b, STATIC)).toEqual([]);
  });

  test('a rootx jump past the threshold is a teleport, and kills velX', () => {
    const a = frameOf(0, row([50, 0, 0]), base);
    const b = frameOf(1, row([0.05, 0, 0]), a);
    expect(halfCheetahDecoder.deriveEvents(a, b, STATIC)).toEqual([{ type: 'teleport' }]);
    expect(b.state.velX).toBe(0);
  });

  test('a jump just under the threshold is motion, not a teleport', () => {
    const a = frameOf(0, row([0, 0, 0]), base);
    const b = frameOf(1, row([CHEETAH_TELEPORT_DX - 0.5, 0, 0]), a);
    expect(halfCheetahDecoder.deriveEvents(a, b, STATIC)).toEqual([]);
    expect(b.state.velX).toBeCloseTo((CHEETAH_TELEPORT_DX - 0.5) / CHEETAH_DT, 6);
  });

  test('done is surfaced when a gym-1000 recording sets it', () => {
    const a = frameOf(0, row([0.1, 0, 0]), base);
    const b = frameOf(1, row([0.2, 0, 0], 1), a);
    expect(halfCheetahDecoder.deriveEvents(a, b, STATIC)).toEqual([{ type: 'done' }]);
  });

  test('a done that also resets rootx reports both', () => {
    const a = frameOf(0, row([80, 0, 0]), base);
    const b = frameOf(1, row([0.01, 0, 0], 1), a);
    expect(halfCheetahDecoder.deriveEvents(a, b, STATIC)).toEqual([
      { type: 'done' },
      { type: 'teleport' },
    ]);
  });
});
